mapper.select:
SELECT 
FROM exam_session_sitting t
WHERE t.session_id = #{sessionId}
  AND t.sitting_no = #{sittingNo}
LIMIT 1

mapper.update:
UPDATE exam_session_sitting
SET status = 'IN_PROGRESS',
    started_at = #{startedAt},
    remaining_sec = #{remainingSec}
WHERE id = #{id}
  AND status = 'PENDING'

UPDATE exam_session_sitting
SET remaining_sec = #{remainingSec},
    current_section_no = #{currentSectionNo},
    objective_score = #{objectiveScore}
WHERE id = #{id}
